INSERT INTO feat VALUES (1,'Blindsight, 5-Ft. Radius','General','No','No',NULL,'Base attack bonus +4, Blind-Fight, Wisdom 19.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Using senses such as acute hearing and sensitivity to vibrations, you detect the location of opponents who are no more than 5 feet away from you. <i>Invisibility</i> and <i>darkness</i> are irrelevant, though it you discern incorporeal beings.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Blindsight, 5-Ft. Radius\" level=\"3\"><p><h3>Blindsight, 5-Ft. Radius [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Base attack bonus +4, Blind-Fight, Wisdom 19.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Using senses such as acute hearing and sensitivity to vibrations, you detect the location of opponents who are no more than 5 feet away from you. <i>Invisibility</i> and <i>darkness</i> are irrelevant, though it you discern incorporeal beings.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (2,'Disguise Spell','Metamagic','No','No',NULL,'Bardic music, Perform 12 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You have mastered the art of casting spells unobtrusively, mingling verbal and somatic components into its music and performances so that others rarely catch you in the act of casting a spell. Like a silent, stilled spell, a disguised spell can\'t be identified through Spellcraft. Your performance is obvious to everyone in the vicinity, but the fact that you are casting a spell isn\'t. Unless the spell visibly emanates from you or observers have some other means of determining its source, they don\'t know where the effect came from. A disguised spell uses up a spell slot one level higher than the spell\'s actual level.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Disguise Spell\" level=\"3\"><p><h3>Disguise Spell [Metamagic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Bardic music, Perform 12 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You have mastered the art of casting spells unobtrusively, mingling verbal and somatic components into its music and performances so that others rarely catch you in the act of casting a spell. Like a silent, stilled spell, a disguised spell can\'t be identified through Spellcraft. Your performance is obvious to everyone in the vicinity, but the fact that you are casting a spell isn\'t. Unless the spell visibly emanates from you or observers have some other means of determining its source, they don\'t know where the effect came from. A disguised spell uses up a spell slot one level higher than the spell\'s actual level.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (3,'Divine Might','Divine','No','No',NULL,'Str 13, turn or rebuke undead ability, Power Attack.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> As a free action, spend one of your turn or rebuke undead attempts to add your Charisma bonus to your weapon damage for 1 full round.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Divine Might\" level=\"3\"><p><h3>Divine Might [Divine ]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Str 13, turn or rebuke undead ability, Power Attack.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> As a free action, spend one of your turn or rebuke undead attempts to add your Charisma bonus to your weapon damage for 1 full round.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (4,'Divine Vengeance','Divine','No','No',NULL,'Ability to turn undead, Extra Turning.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can spend one of your turn undead attempts to add 2d6 points of sacred energy damage to all your successful melee attacks against undead until the end of your next action. This is a supernatural ability.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Divine Vengeance\" level=\"3\"><p><h3>Divine Vengeance [Divine ]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Ability to turn undead, Extra Turning.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can spend one of your turn undead attempts to add 2d6 points of sacred energy damage to all your successful melee attacks against undead until the end of your next action. This is a supernatural ability.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (5,'Energy Substitution','Metamagic','Yes','No','One type of energy: acid, cold, electricity, fire, or sonic','Any other metamagic feat, Knowledge (arcana) 5 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You choose one type of energy: acid, cold, electricity, fire, or sonic. When employing a spell with the acid, cold, electricity, fire, or sonic designator, you can modify the spell to use your chosen type of energy instead. The altered spell uses a spell slot of the spell\'s normal level.</p><p>The altered spell works normally in all respects except the type of damage dealt.</p>\n</div>\n',NULL,'You can gain this feat multiple times. Each time the feat applies to a different type of energy.','\n      <div topic=\"Energy Substitution\" level=\"3\"><p><h3>Energy Substitution [Metamagic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Any other metamagic feat, Knowledge (arcana) 5 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You choose one type of energy: acid, cold, electricity, fire, or sonic. When employing a spell with the acid, cold, electricity, fire, or sonic designator, you can modify the spell to use your chosen type of energy instead. The altered spell uses a spell slot of the spell\'s normal level.</p><p>The altered spell works normally in all respects except the type of damage dealt.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can gain this feat multiple times. Each time the feat applies to a different type of energy.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (6,'Extra Music','General','Yes','Yes',NULL,'Bardic music.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can use your bardic music four extra times per day.</p>\n</div>\n','Bards without the Extra Music feat can use bardic music once per day per level.','You can gain this feat multiple times, adding another four uses of bardic music each time.','\n      <div topic=\"Extra Music\" level=\"3\"><p><h3>Extra Music [General]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Bardic music.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can use your bardic music four extra times per day.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Bards without the Extra Music feat can use bardic music once per day per level.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can gain this feat multiple times, adding another four uses of bardic music each time.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (7,'Eyes in the Back of Your Head','General','No','No',NULL,'Base attack bonus +3, Wis 19.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Attackers do not gain the usual +2 attack bonus when flanking you. This feat grants no effect whenever you are attacked without benefit of your Dexterity modifier to AC, such as when you are flat-footed or when you are the target of a rogue\'s sneak attack.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Eyes in the Back of Your Head\" level=\"3\"><p><h3>Eyes in the Back of Your Head [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Base attack bonus +3, Wis 19.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Attackers do not gain the usual +2 attack bonus when flanking you. This feat grants no effect whenever you are attacked without benefit of your Dexterity modifier to AC, such as when you are flat-footed or when you are the target of a rogue\'s sneak attack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (8,'Fleet of Foot','General','No','No',NULL,'Dex 15, Run.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When running or charging, you can make a single direction change of 90 degrees or less. You can\'t use this feat while wearing medium or heavy armor, or when carrying a medium or heavy load.  If you are charging, you must move in a straight line for 10 feet after the turn to maintain the charge.</p>\n</div>\n','Without this feat, you can run or charge only in a straight line.',NULL,'\n      <div topic=\"Fleet of Foot\" level=\"3\"><p><h3>Fleet of Foot [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Dex 15, Run.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When running or charging, you can make a single direction change of 90 degrees or less. You can\'t use this feat while wearing medium or heavy armor, or when carrying a medium or heavy load.  If you are charging, you must move in a straight line for 10 feet after the turn to maintain the charge.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, you can run or charge only in a straight line.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (9,'Hold the Line','General','No','No',NULL,'Combat Reflexes, base attack bonus +2.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You may make an attack of opportunity against a chagin opponent who enters an atea you threaten.  Your attack of opportunity happens immediately before the charge attack is resolved.</p>\n</div>\n','You only get an attack of opportunity against a character that exits a square you threaten.',NULL,'\n      <div topic=\"Hold the Line\" level=\"3\"><p><h3>Hold the Line [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Combat Reflexes, base attack bonus +2.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You may make an attack of opportunity against a chagin opponent who enters an atea you threaten.  Your attack of opportunity happens immediately before the charge attack is resolved.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> You only get an attack of opportunity against a character that exits a square you threaten.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (10,'Jack of all Trades','General','No','No',NULL,'You must be at least 6th level.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can use any skill untrained, even those that normally require training.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Jack of all Trades\" level=\"3\"><p><h3>Jack of all Trades [General]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> You must be at least 6th level.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can use any skill untrained, even those that normally require training.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (11,'Knock-Down','General','No','No',NULL,'Base attack bonus +2, Improved Trip, Str 15.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever you deal 10 or more points of damage to your opponent in melee, you make a trip attack as a free action against the same target.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Knock-Down\" level=\"3\"><p><h3>Knock-Down [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Base attack bonus +2, Improved Trip, Str 15.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever you deal 10 or more points of damage to your opponent in melee, you make a trip attack as a free action against the same target.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (12,'Persistent Spell','Metamagic','No','No',NULL,'Extend Spell.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> A persistent spell has a duration of 24 hours. The persistent spell must have a personal range or a fixed range. Spells of instantaneous duration cannot be affected by this feat, nor can spells whose effects are discharged.  You need not concentrate on spells such as <i>detect magic</i> or <i>detect thoughts</i> to be aware of the mere presence of absence of the things detected, but you must still concentrate to gain additional information as normal.  Concentration on such a spell is a standard action that does not provoke an attack of opportunity.  A persistent spell uses up a spell slot six levels higher than the spell\'s actual level.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Persistent Spell\" level=\"3\"><p><h3>Persistent Spell [Metamagic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Extend Spell.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> A persistent spell has a duration of 24 hours. The persistent spell must have a personal range or a fixed range. Spells of instantaneous duration cannot be affected by this feat, nor can spells whose effects are discharged.  You need not concentrate on spells such as <i>detect magic</i> or <i>detect thoughts</i> to be aware of the mere presence of absence of the things detected, but you must still concentrate to gain additional information as normal.  Concentration on such a spell is a standard action that does not provoke an attack of opportunity.  A persistent spell uses up a spell slot six levels higher than the spell\'s actual level.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (13,'Plant Control','General','No','No',NULL,'Plant Defiance, ability to cast speak with plants.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can rebuke or command plant creatures as an evil cleric rebukes undead. To command a plant, you must be able to speak with it via a <i>speak with plants</i> effect, though it may do so mentally if desired. This ability is usable a total number of times per day equal to 3 + your Charisma modifier. You use your highest caster level to determine the level at which you rebuke plants.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Plant Control\" level=\"3\"><p><h3>Plant Control [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Plant Defiance, ability to cast <i>speak with plants</i>.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can rebuke or command plant creatures as an evil cleric rebukes undead. To command a plant, you must be able to speak with it via a <i>speak with plants</i> effect, though it may do so mentally if desired. This ability is usable a total number of times per day equal to 3 + your Charisma modifier. You use your highest caster level to determine the level at which you rebuke plants.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (14,'Plant Defiance','General','No','No',NULL,'Ability to cast detect animals or plants.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can turn (but not destroy) plant creatures as a good cleric turns undead. When determining the result of a turning attempt, treat all destruction results as normal turning. Treat immobile plant creatures as creatures unable to flee. This ability is usable a total number of times per day equal to 3 + your Charisma modifier. You use your highest caster level to determine the level at which you turns plants.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Plant Defiance\" level=\"3\"><p><h3>Plant Defiance [General]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Ability to cast <i>detect animals or plants</i>.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You can turn (but not destroy) plant creatures as a good cleric turns undead. When determining the result of a turning attempt, treat all destruction results as normal turning. Treat immobile plant creatures as creatures unable to flee. This ability is usable a total number of times per day equal to 3 + your Charisma modifier. You use your highest caster level to determine the level at which you turns plants.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (15,'Power Critical','General','Yes','Yes','Weapon','Weapon focus (chosen weapon), base attack bonus +4','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When using the weapon you selected, you gain a +4 bonus on the roll to confirm a threat.</p>\n</div>\n',NULL,'A fighter may select Power Critical as one of his fighter bonus feats.You can gain Power Critical multiple times. Each time you take the feat, it may be with a different weapon or the same weapon. If you take it with the same weapon, the effects of the feats stack.','\n      <div topic=\"Power Critical\" level=\"3\"><p><h3>Power Critical [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Weapon focus (chosen weapon), base attack bonus +4</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When using the weapon you selected, you gain a +4 bonus on the roll to confirm a threat.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A fighter may select Power Critical as one of his fighter bonus feats.</p><p>You can gain Power Critical multiple times. Each time you take the feat, it may be with a different weapon or the same weapon.  If you take it with the same weapon, the effects of the feats stack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (16,'Reach Spell','Metamagic','No','No',NULL,NULL,'<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You may cast a spell that normally has a range of touch at any distance up to 30 feet. The spell effectively becomes a ray, so you must succeed at a ranged touch attack to bestow the spell upon the recipient. A reach spell uses up a spell slot two levels higher than the spell\'s actual level.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Reach Spell\" level=\"3\"><p><h3>Reach Spell [Metamagic]</h3></p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You may cast a spell that normally has a range of touch at any distance up to 30 feet. The spell effectively becomes a ray, so you must succeed at a ranged touch attack to bestow the spell upon the recipient. A reach spell uses up a spell slot two levels higher than the spell\'s actual level.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (17,'Repeat Spell','Metamagic','No','No',NULL,'Any other metamagic feat.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> A repeated spell is automatically cast again at the beginning of your next round of actions. No matter where you are, the secondary spell originates from the same location and affects the same area as the primary spell. If the repeated spell designates a target, the secondary spell retargets the same target if the target is within 30 feet of its original position; otherwise the secondary spell fails to go off. A repeated spell uses up a spell slot three levels higher than the spell\'s actual level. Repeat Spell cannot be used on spells with a range of touch.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Repeat Spell\" level=\"3\"><p><h3>Repeat Spell [Metamagic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Any other metamagic feat.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> A repeated spell is automatically cast again at the beginning of your next round of actions. No matter where you are, the secondary spell originates from the same location and affects the same area as the primary spell. If the repeated spell designates a target, the secondary spell retargets the same target if the target is within 30 feet of its original position; otherwise the secondary spell fails to go off. A repeated spell uses up a spell slot three levels higher than the spell\'s actual level. Repeat Spell cannot be used on spells with a range of touch.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (18,'Sacred Spell','Metamagic','No','No',NULL,NULL,'<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Half of the damage dealt by a sacred spell results directly from divine power and is therefore not subject to being reduced by protection from energy or similar magic. The other half of the damage dealt by the spell is as normal. A sacred spell uses up a spell slot two levels higher than the spell\'s actual level. Only divine spells can be cast as sacred spells.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Sacred Spell\" level=\"3\"><p><h3>Sacred Spell [Metamagic]</h3></p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Half of the damage dealt by a sacred spell results directly from divine power and is therefore not subject to being reduced by protection from energy or similar magic. The other half of the damage dealt by the spell is as normal. A sacred spell uses up a spell slot two levels higher than the spell\'s actual level. Only divine spells can be cast as sacred spells.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (19,'Sharp-Shooting','General','No','No',NULL,'Point Blank Shot, Precise Shot, base attack bonus +3.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Your targets only receive a +2 bonus to Armor class due to cover.  This feat has no effect against foes with no cover or total cover.</p>\n</div>\n','Cover normally gives a +4 bonus to AC.','A fighter may select Sharp-Shooting as one of his bonus feats.','\n      <div topic=\"Sharp-Shooting\" level=\"3\"><p><h3>Sharp-Shooting [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Point Blank Shot, Precise Shot, base attack bonus +3.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Your targets only receive a +2 bonus to Armor class due to cover.  This feat has no effect against foes with no cover or total cover.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Cover normally gives a +4 bonus to AC.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A fighter may select Sharp-Shooting as one of his bonus feats.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (20,'Subdual Substitution','Metamagic','No','No',NULL,'Any other metamagic feat, Knowledge (arcana) 5 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When employing a spell with the acid, cold, electricity, fire, or sonic designator, you can modify the spell to deal subdual damage instead of the indicated type of energy damage. The altered spell uses a spell slot of the spell\'s normal level.</p><p>The altered spell works normally in all respects except the type of damage dealt.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Subdual Substitution\" level=\"3\"><p><h3>Subdual Substitution [Metamagic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Any other metamagic feat, Knowledge (arcana) 5 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When employing a spell with the acid, cold, electricity, fire, or sonic designator, you can modify the spell to deal subdual damage instead of the indicated type of energy damage. The altered spell uses a spell slot of the spell\'s normal level.</p><p>The altered spell works normally in all respects except the type of damage dealt.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (21,'Superior Expertise','General','No','No',NULL,'Int 13, Combat Expertise, base attack bonus +6.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When you use the Combat Expertise feat to improve your Armor Class, the number you subtract from your attack and add to your AC can be any number that does not exceed your base attack bonus.</p><p>This feat eliminates the +5 maximum for the Combat Expertise feat.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Superior Expertise\" level=\"3\"><p><h3>Superior Expertise [General]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Int 13, Combat Expertise, base attack bonus +6.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> When you use the Combat Expertise feat to improve your Armor Class, the number you subtract from your attack and add to your AC can be any number that does not exceed your base attack bonus.</p><p>This feat eliminates the +5 maximum for the Combat Expertise feat.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 DivineAbilitiesandFeats');
INSERT INTO feat VALUES (22,'Additional Magic Item Space','Epic','Yes','No','One type of magic item that has a limit on the number a character can simultaneously wear and gain its benefit',NULL,'<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Choose one type of magic item that has a limit on the number a character can simultaneously wear and gain its benefit. The character can now wear one more magic item of this type and also gain its benefit.</p>\n</div>\n','Without this feat, a character is limited to one headband, hat, or helmet; one pair of eye lenses or goggles; one cloak, cape, or mantle; one amulet, brooch, medallion, necklace, periapt, or scarab; one suit of armor; one robe; one vest, vestment, or shirt; one pair of bracers or bracelets; one pair of gloves or gauntlets; two rings; one belt; and one pair of boots.','A character can gain this feat multiple times. Each time the character takes the feat, it applies to a new type of wearable magic item.','\n      <div topic=\"Additional Magic Item Space\" level=\"3\"><p><h3>Additional Magic Item Space [Epic]</h3></p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Choose one type of magic item that has a limit on the number a character can simultaneously wear and gain its benefit. The character can now wear one more magic item of this type and also gain its benefit.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, a character is limited to one headband, hat, or helmet; one pair of eye lenses or goggles; one cloak, cape, or mantle; one amulet, brooch, medallion, necklace, periapt, or scarab; one suit of armor; one robe; one vest, vestment, or shirt; one pair of bracers or bracelets; one pair of gloves or gauntlets; two rings; one belt; and one pair of boots.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Each time the character takes the feat, it applies to a new type of wearable magic item.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (23,'Armor Skin','Epic','Yes','Yes',NULL,NULL,'<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character gains a +1 natural armor bonus to Armor Class, or his or her existing natural armor bonus increases by 1.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Its effects stack.','\n      <div topic=\"Armor Skin\" level=\"3\"><p><h3>Armor Skin [Epic]</h3></p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character gains a +1 natural armor bonus to Armor Class, or his or her existing natural armor bonus increases by 1.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Its effects stack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (24,'Augmented Alchemy','Epic','No','No',NULL,'Int 21, Craft(alchemy) 24 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever creating an alchemical item or substance, the character can choose to make it more powerful than normal by adding +20 to the DC required to create it and multiplying its price by 5. If the item or substance deals damage, double the damage dealt. If the item or substance doesn\'t deal damage, double the duration of its effect. If the item or substance doesn\'t deal damage and doesn\'t have a specific listed duration (or has an instantaneous duration), double all dimensions of its area. If the item or substance doesn\'t fit any of these categories, then it cannot be affected by this feat. See the Craft (alchemy) skill description.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Augmented Alchemy\" level=\"3\"><p><h3>Augmented Alchemy [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Int 21, Craft(alchemy) 24 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever creating an alchemical item or substance, the character can choose to make it more powerful than normal by adding +20 to the DC required to create it and multiplying its price by 5. If the item or substance deals damage, double the damage dealt. If the item or substance doesn\'t deal damage, double the duration of its effect. If the item or substance doesn\'t deal damage and doesn\'t have a specific listed duration (or has an instantaneous duration), double all dimensions of its area. If the item or substance doesn\'t fit any of these categories, then it cannot be affected by this feat. See the Craft (alchemy) skill description.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (25,'Automatic Quicken Spell','Epic','Yes','Yes',NULL,'Quicken Spell, Spellcraft 30 ranks, ability to cast 9th-level arcane or divine spells.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may cast all 0-, 1st-, 2nd-, and 3rd-level spells as quickened spells without using higher-level spell slots. The normal limit to the number of quickened spells a character may cast per round applies. Spells with a casting time of more than 1 full round can\'t be quickened.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Each time a character takes the feat, the spells of his or her next three lowest spell levels can now be quickened with no adjustment to their spell slots. This feat doesn\'t increase the casting time for those spells that normally become full-round actions when cast in metamagic form.','\n      <div topic=\"Automatic Quicken Spell\" level=\"3\"><p><h3>Automatic Quicken Spell [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Quicken Spell, Spellcraft 30 ranks, ability to cast 9th-level arcane or divine spells.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may cast all 0-, 1st-, 2nd-, and 3rd-level spells as quickened spells without using higher-level spell slots. The normal limit to the number of quickened spells a character may cast per round applies. Spells with a casting time of more than 1 full round can\'t be quickened.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Each time a character takes the feat, the spells of his or her next three lowest spell levels can now be quickened with no adjustment to their spell slots. This feat doesn\'t increase the casting time for those spells that normally become full-round actions when cast in metamagic form.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (26,'Automatic Silent Spell','Epic','Yes','Yes',NULL,'Silent Spell, Spellcraft 24 ranks, ability to cast 9th-level arcane or divine spells.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may cast all 0-, 1st-, 2nd-, and 3rd-level spells as silent spells without using higher-level spell slots.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Each time a character takes the feat, the spells of his or her next three lowest spell levels can now be silenced with no adjustment to their spell slots. This feat doesn\'t increase the casting time for those spells that normally become full-round actions when cast in metamagic form. However, since bard spells can\'t be enhanced with the Silent Spell feat, they can\'t be affected by this feat either.','\n      <div topic=\"Automatic Silent Spell\" level=\"3\"><p><h3>Automatic Silent Spell [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Silent Spell, Spellcraft 24 ranks, ability to cast 9th-level arcane or divine spells.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may cast all 0-, 1st-, 2nd-, and 3rd-level spells as silent spells without using higher-level spell slots.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Each time a character takes the feat, the spells of his or her next three lowest spell levels can now be silenced with no adjustment to their spell slots. This feat doesn\'t increase the casting time for those spells that normally become full-round actions when cast in metamagic form. However, since bard spells can\'t be enhanced with the Silent Spell feat, they can\'t be affected by this feat either.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (27,'Automatic Still Spell','Epic','Yes','Yes',NULL,'Still Spell, Spellcraft 27 ranks, ability to cast 9th-level arcane or divine spells.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may cast all 0-, 1st-, 2nd-, and 3rd-level spells as stilled spells without using higher-level spell slots.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Each time a character takes the feat, the spells of his or her next three lowest spell levels can now be stilled with no adjustment to their spell slots. This feat doesn\'t increase the casting time for those spells that normally become full-round actions when cast in metamagic form.','\n      <div topic=\"Automatic Still Spell\" level=\"3\"><p><h3>Automatic Still Spell [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Still Spell, Spellcraft 27 ranks, ability to cast 9th-level arcane or divine spells.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may cast all 0-, 1st-, 2nd-, and 3rd-level spells as stilled spells without using higher-level spell slots.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Each time a character takes the feat, the spells of his or her next three lowest spell levels can now be stilled with no adjustment to their spell slots. This feat doesn\'t increase the casting time for those spells that normally become full-round actions when cast in metamagic form.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (28,'Bane of Enemies','Epic','No','No',NULL,'Survival 24 ranks, five or more favored enemies.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Any weapon the character wields against one of his or her favored enemies is treated as a bane weapon for that creature type (thus, its enhancement bonus is increased by +2 and it deals +2d6 points of damage). This ability doesn\'t stack with similar abilities.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Bane of Enemies\" level=\"3\"><p><h3>Bane of Enemies [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Survival 24 ranks, five or more favored enemies.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Any weapon the character wields against one of his or her favored enemies is treated as a bane weapon for that creature type (thus, its enhancement bonus is increased by +2 and it deals +2d6 points of damage). This ability doesn\'t stack with similar abilities.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (29,'Blinding Speed','Epic','Yes','Yes',NULL,'Dex 25.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can act as if <i>hasted</i> for 5 rounds each day. The duration of the effect need not be consecutive rounds. Activating this power is a free action.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Each time he or she takes the feat, it grants an additional 5 rounds of haste per day.','\n      <div topic=\"Blinding Speed\" level=\"3\"><p><h3>Blinding Speed [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Dex 25.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can act as if <i>hasted</i> for 5 rounds each day. The duration of the effect need not be consecutive rounds. Activating this power is a free action.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Each time he or she takes the feat, it grants an additional 5 rounds of <i>haste</i> per day.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (30,'Bonus Domain','Epic','Yes','No','An additional domain from the character\'s deity\'s domain list','Wis 21, ability to cast 9th-level divine spells.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Choose an additional domain from the character\'s deity\'s domain list. The character now has access to that domain\'s spells as normal for his or her domain spells and the domain\'s granted powers.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Each time he or she takes the feat, it applies to a different domain.','\n      <div topic=\"Bonus Domain\" level=\"3\"><p><h3>Bonus Domain [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Wis 21, ability to cast 9th-level divine spells.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Choose an additional domain from the character\'s deity\'s domain list. The character now has access to that domain\'s spells as normal for his or her domain spells and the domain\'s granted powers.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Each time he or she takes the feat, it applies to a different domain.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (31,'Bulwark of Defense','Epic','No','No',NULL,'Con 25, defensive stance 3/day.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character\'s defensive stance bonuses increase to +4 Strength, +6 Constitution, +4 resistance bonus on all saves, and +6 dodge bonus to AC.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Bulwark of Defense\" level=\"3\"><p><h3>Bulwark of Defense [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Con 25, defensive stance 3/day.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character\'s defensive stance bonuses increase to +4 Strength, +6 Constitution, +4 resistance bonus on all saves, and +6 dodge bonus to AC.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (32,'Chaotic Rage','Epic','No','No',NULL,'Rage 5/day, chaotic alignment.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Any weapon the character wields while in a rage is treated as an anarchic weapon (it is chaos-aligned and deals an extra 2d6 points of damage against creatures of lawful alignment). This ability does not stack with similar abilities.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Chaotic Rage\" level=\"3\"><p><h3>Chaotic Rage [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Rage 5/day, chaotic alignment.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Any weapon the character wields while in a rage is treated as an anarchic weapon (it is chaos-aligned and deals an extra 2d6 points of damage against creatures of lawful alignment). This ability does not stack with similar abilities.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (33,'Colossal Wild Shape','Wild, Epic','No','No',NULL,'The ability to wild shape into a Gargantuan creature.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can use his or her <i>wild shape</i> to take the shape of a Colossal animal.</p>\n</div>\n','Without this feat, a character cannot wild shape into an animal of greater than Huge size.',NULL,'\n      <div topic=\"Colossal Wild Shape\" level=\"3\"><p><h3>Colossal Wild Shape [Wild] [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> The ability to <i>wild shape</i> into a Gargantuan creatur<i>e</i>.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can use his or her <i>wild shape</i> to take the shape of a Colossal animal.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, a character cannot <i>wild shape</i> into an animal of greater than Huge size.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (34,'Combat Archery','Epic','No','No',NULL,'Dodge, Mobility, Point Blank Shot.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character does not incur any attacks of opportunity for firing a bow when threatened.</p>\n</div>\n','Without this feat, a character incurs an attack of opportunity from all opponents who threaten him or her whenever he or she uses a bow.',NULL,'\n      <div topic=\"Combat Archery\" level=\"3\"><p><h3>Combat Archery [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Dodge, Mobility, Point Blank Shot.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character does not incur any attacks of opportunity for firing a bow when threatened.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, a character incurs an attack of opportunity from all opponents who threaten him or her whenever he or she uses a bow.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (35,'Craft Epic Magic Arms and Armor','Item Creation, Epic','No','No',NULL,'Craft Magic Arms and Armor, Knowledge (arcana) 28 ranks, Spellcraft 28 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft magic arms and armor which exceed the normal limits for such items</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Craft Epic Magic Arms and Armor\" level=\"3\"><p><h3>Craft Epic Magic Arms and Armor [Item Creation] [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Craft Magic Arms and Armor, Knowledge (arcana) 28 ranks, Spellcraft 28 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft magic arms and armor which exceed the normal limits for such items</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (36,'Craft Epic Rod','Item Creation, Epic','No','No',NULL,'Craft Rod, Knowledge (arcana) 32 ranks, Spellcraft 32 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft rods that exceed the normal limits for such items.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Craft Epic Rod\" level=\"3\"><p><h3>Craft Epic Rod [Item Creation] [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Craft Rod, Knowledge (arcana) 32 ranks, Spellcraft 32 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft rods that exceed the normal limits for such items.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (37,'Craft Epic Staff','Item Creation, Epic','No','No',NULL,'Craft Staff, Knowledge (arcana) 35 ranks, Spellcraft 35 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft staffs that exceed the normal limits for such items.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Craft Epic Staff\" level=\"3\"><p><h3>Craft Epic Staff [Item Creation] [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Craft Staff, Knowledge (arcana) 35 ranks, Spellcraft 35 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft staffs that exceed the normal limits for such items.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (38,'Craft Epic Wondrous Item','Item Creation, Epic','No','No',NULL,'Craft Wondrous Item, Knowledge (arcana) 26 ranks, Spellcraft 26 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft wondrous items that exceed the normal limits for such items.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Craft Epic Wondrous Item\" level=\"3\"><p><h3>Craft Epic Wondrous Item [Item Creation] [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Craft Wondrous Item, Knowledge (arcana) 26 ranks, Spellcraft 26 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can craft wondrous items that exceed the normal limits for such items.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (39,'Damage Reduction','Epic','Yes','Yes',NULL,'Con 21.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character gains damage reduction 3/-. This does not stack with damage reduction granted by magic items or nonpermanent magical effects, but it does stack with any damage reduction granted by permanent magical effects, class features, or this feat itself.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Each time he or she gains the feat, his or her damage reduction increases by 3.','\n      <div topic=\"Damage Reduction\" level=\"3\"><p><h3>Damage Reduction [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Con 21.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character gains damage reduction 3/-. This does not stack with damage reduction granted by magic items or nonpermanent magical effects, but it does stack with any damage reduction granted by permanent magical effects, class features, or this feat itself.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Each time he or she gains the feat, his or her damage reduction increases by 3.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (40,'Deafening Song','Epic','No','No',NULL,'Perform 24 ranks, bardic music class feature.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can use song or poetics to temporarily deafen all enemies within a 30-foot spread from him or her. A successful Fortitude save (DC 10 + 1/2 the character\'s class level + the character\'s Charisma modifier) negates the effect. The deafening effect lasts for as long as the character continues the deafening song. The character can choose to exclude any characters from this effect. The character may sing, play, or recite a deafening song while taking other mundane actions, but not magical ones (see the bard\'s inspire courage ability for more details). The character may keep up the deafening song for a maximum of 10 rounds. Using the deafening song counts as one of the character\'s uses of song or poetics for the day.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Deafening Song\" level=\"3\"><p><h3>Deafening Song [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Perform 24 ranks, bardic music class feature.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can use song or poetics to temporarily deafen all enemies within a 30-foot spread from him or her. A successful Fortitude save (DC 10 + 1/2 the character\'s class level + the character\'s Charisma modifier) negates the effect. The deafening effect lasts for as long as the character continues the deafening song. The character can choose to exclude any characters from this effect. The character may sing, play, or recite a deafening song while taking other mundane actions, but not magical ones (see the bard\'s inspire courage ability for more details). The character may keep up the deafening song for a maximum of 10 rounds. Using the deafening song counts as one of the character\'s uses of song or poetics for the day.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (41,'Death of Enemies','Epic','No','No',NULL,'Bane of Enemies, Survival 30 ranks, five or more favored enemies.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Any time the character scores a critical hit against one of his or her favored enemies, it must make a Fortitude save (DC 10 + 1/2 character\'s ranger class level + character\'s Wisdom modifier) or die instantly.</p>\n</div>\n',NULL,'Creatures immune to critical hits can\'t be affected by this feat.','\n      <div topic=\"Death of Enemies\" level=\"3\"><p><h3>Death of Enemies [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Bane of Enemies, Survival 30 ranks, five or more favored enemies.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Any time the character scores a critical hit against one of his or her favored enemies, it must make a Fortitude save (DC 10 + 1/2 character\'s ranger class level + character\'s Wisdom modifier) or die instantly.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> Creatures immune to critical hits can\'t be affected by this feat.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (42,'Devastating Critical','Epic','Yes','No','A different type of weapon','Str 25, Cleave, Great Cleave, Improved Critical (chosen weapon), Overwhelming Critical (chosen weapon), Power Attack, Weapon Focus (chosen weapon).','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever the character scores a critical hit with the chosen weapon, the target must make a Fortitude save (DC 10 + 1/2 character level + character\'s Strength modifier) or die instantly. (Creatures immune to critical hits can\'t be affected by this feat.)</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Its effects do not stack. Each time a character takes the feat, it applies to a different type of weapon.','\n      <div topic=\"Devastating Critical\" level=\"3\"><p><h3>Devastating Critical [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Str 25, Cleave, Great Cleave, Improved Critical (chosen weapon), Overwhelming Critical (chosen weapon), Power Attack, Weapon Focus (chosen weapon).</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever the character scores a critical hit with the chosen weapon, the target must make a Fortitude save (DC 10 + 1/2 character level + character\'s Strength modifier) or die instantly. (Creatures immune to critical hits can\'t be affected by this feat.)</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Its effects do not stack. Each time a character takes the feat, it applies to a different type of weapon.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (43,'Dexterous Fortitude','Epic','No','No',NULL,'Dex 25, slippery mind class feature.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Once per round, when targeted by an effect that requires a Fortitude saving throw, the character may make a Reflex save instead to avoid the effect (evasion is not applicable).</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Dexterous Fortitude\" level=\"3\"><p><h3>Dexterous Fortitude [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Dex 25, slippery mind class feature.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Once per round, when targeted by an effect that requires a Fortitude saving throw, the character may make a Reflex save instead to avoid the effect (evasion is not applicable).</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (44,'Dexterous Will','Epic','No','No',NULL,'Dex 25, slippery mind class feature.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Once per round, when targeted by an effect that requires a Will saving throw, the character may make a Reflex save instead to avoid the effect (evasion is not applicable).</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Dexterous Will\" level=\"3\"><p><h3>Dexterous Will [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Dex 25, slippery mind class feature.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Once per round, when targeted by an effect that requires a Will saving throw, the character may make a Reflex save instead to avoid the effect (evasion is not applicable).</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (45,'Diminutive Wild Shape','Wild, Epic','No','No',NULL,'Ability to wild shape into a Huge animal.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can use <i>wild shape</i> to take the shape of a Diminutive animal.</p>\n</div>\n','Without this feat, a character cannot wild shape into an animal of smaller than Tiny size.',NULL,'\n      <div topic=\"Diminutive Wild Shape\" level=\"3\"><p><h3>Diminutive Wild Shape [Wild] [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Ability to <i>wild shape</i> into a Huge animal.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character can use <i>wild shape</i> to take the shape of a Diminutive animal.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, a character cannot <i>wild shape</i> into an animal of smaller than Tiny size.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (46,'Dire Charge','Epic','No','No',NULL,'Improved Initiative.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> If the character charges a foe during the first round of combat (or the surprise round, if the character is allowed to act in it), he or she can make a full attack against the opponent charged.</p>\n</div>\n','Without this feat, a character may only make a single attack as part of a charge.',NULL,'\n      <div topic=\"Dire Charge\" level=\"3\"><p><h3>Dire Charge [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Improved Initiative.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> If the character charges a foe during the first round of combat (or the surprise round, if the character is allowed to act in it), he or she can make a full attack against the opponent charged.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, a character may only make a single attack as part of a charge.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (47,'Distant Shot','Epic','No','No',NULL,'Dex 25, Far Shot, Point Blank Shot, Spot 20 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may throw or fire a ranged weapon at any target within line of sight, with no penalty for range.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Distant Shot\" level=\"3\"><p><h3>Distant Shot [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Dex 25, Far Shot, Point Blank Shot, Spot 20 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may throw or fire a ranged weapon at any target within line of sight, with no penalty for range.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (48,'Dragon Wild Shape','Wild, Epic','No','No',NULL,'Wis 30, Knowledge (nature) 30 ranks, wild shape 6/day.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may use <i>wild shape</i> to change into a dragon (black, blue, green, red, white, brass, bronze, copper, gold, or silver). The size limitation is the same as the character\'s limitation on animal size. The character gains all extraordinary and supernatural abilities of the dragon whose form he or she takes.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Dragon Wild Shape\" level=\"3\"><p><h3>Dragon Wild Shape [Wild] [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Wis 30, Knowledge (nature) 30 ranks, <i>wild shape</i> 6/day.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character may use <i>wild shape</i> to change into a dragon (black, blue, green, red, white, brass, bronze, copper, gold, or silver). The size limitation is the same as the character\'s limitation on animal size. The character gains all extraordinary and supernatural abilities of the dragon whose form he or she takes.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (49,'Efficient Item Creation','Epic','Yes','No','An item creation feat','Item creation feat to be selected, Knowledge (arcana) 24 ranks, Spellcraft 24 ranks.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Select an item creation feat. Creating a magic item using that feat requires one day per 10,000 gp of the item\'s market price, with a minimum of one day.</p>\n</div>\n','Without this feat, creating a magic item requires one day for each 1,000 gp of the item\'s market price.','A character can gain this feat multiple times. Its effects do not stack. Each time a character takes the feat, it applies to a different item creation feat.','\n      <div topic=\"Efficient Item Creation\" level=\"3\"><p><h3>Efficient Item Creation [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Item creation feat to be selected, Knowledge (arcana) 24 ranks, Spellcraft 24 ranks.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Select an item creation feat. Creating a magic item using that feat requires one day per 10,000 gp of the item\'s market price, with a minimum of one day.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, creating a magic item requires one day for each 1,000 gp of the item\'s market price.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Its effects do not stack. Each time a character takes the feat, it applies to a different item creation feat.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (50,'Energy Resistance','Epic','Yes','Yes','A type of energy (acid, cold, electricity, fire, or sonic)',NULL,'<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Choose a type of energy (acid, cold, electricity, fire, or sonic). The character gains resistance 10 to that type of energy, or the character\'s existing resistance to that type of energy increases by 10. This feat does not stack with energy resistance granted by magic items or nonpermanent magical effects.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. If the same type of energy is chosen, the effects stack.','\n      <div topic=\"Energy Resistance\" level=\"3\"><p><h3>Energy Resistance [Epic]</h3></p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Choose a type of energy (acid, cold, electricity, fire, or sonic). The character gains resistance 10 to that type of energy, or the character\'s existing resistance to that type of energy increases by 10. This feat does not stack with energy resistance granted by magic items or nonpermanent magical effects.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. If the same type of energy is chosen, the effects stack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (51,'Enhance Spell','Metamagic, Epic','Yes','Yes',NULL,'Maximize Spell.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The damage cap for the character\'s spells increases by 10 dice (for spells that deal a number of dice of damage equal to caster level) or by 5 dice (for spells that deal a number of dice of damage equal to half caster level). An enhanced spell uses up a spell slot four levels higher than the spell\'s actual level. This feat has no effect on spells that don\'t specifically deal a number of dice of damage equal to the caster\'s level or half level, even if the spell\'s effect is largely dictated by the caster\'s level.</p>\n</div>\n','Without this feat, use the damage dice caps indicated in the spell\'s description.','A character may gain this feat multiple times. Each time he or she selects this feat, the damage cap increases by 10 dice or 5 dice, as appropriate to the spell, and the enhanced spell takes up a spell slot an additional four levels higher.','\n      <div topic=\"Enhance Spell\" level=\"3\"><p><h3>Enhance Spell [Metamagic] [Epic]</h3></p><div topic=\"Prerequisite\" level=\"8\"><p><b>Prerequisite:</b> Maximize Spell.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The damage cap for the character\'s spells increases by 10 dice (for spells that deal a number of dice of damage equal to caster level) or by 5 dice (for spells that deal a number of dice of damage equal to half caster level). An enhanced spell uses up a spell slot four levels higher than the spell\'s actual level. This feat has no effect on spells that don\'t specifically deal a number of dice of damage equal to the caster\'s level or half level, even if the spell\'s effect is largely dictated by the caster\'s level.</p>\n</div><div topic=\"Normal\" level=\"8\"><p><b>Normal:</b> Without this feat, use the damage dice caps indicated in the spell\'s description.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character may gain this feat multiple times. Each time he or she selects this feat, the damage cap increases by 10 dice or 5 dice, as appropriate to the spell, and the enhanced spell takes up a spell slot an additional four levels higher.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (52,'Epic Dodge','Epic','No','No',NULL,'Dex 25, Dodge, Tumble 30 ranks, improved evasion, defensive roll class feature.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Once per round, when struck by an attack from an opponent the character has designated as the object of his or her dodge, the character may automatically avoid all damage from the attack.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Epic Dodge\" level=\"3\"><p><h3>Epic Dodge [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Dex 25, Dodge, Tumble 30 ranks, improved evasion, defensive roll class feature.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Once per round, when struck by an attack from an opponent the character has designated as the object of his or her dodge, the character may automatically avoid all damage from the attack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (53,'Epic Endurance','Epic','No','No',NULL,'Con 25, Endurance.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever the character makes a check for performing a physical action that extends over a period of time, he or she gets a +10 bonus on the check.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Epic Endurance\" level=\"3\"><p><h3>Epic Endurance [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Con 25, Endurance.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> Whenever the character makes a check for performing a physical action that extends over a period of time, he or she gets a +10 bonus on the check.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (54,'Epic Expanded Knowledge','Epic, Psionic','Yes','No','Any power, even one that is part of another discipline\'s list or another class\'s list','Character level 21st, ability to manifest powers of the normal maximum power level in at least one psionic class.','<p>You learn another power.</p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You learn one additional power at any level up to the highest level of power you can manifest. You can choose any power, even one that is part of another discipline\'s list or another class\'s list.</p>\n</div>\n',NULL,'You can gain this feat multiple times. Each time, you learn one new power at any level up to the highest level of power you can manifest.','\n      <div topic=\"Epic Expanded Knowledge\" level=\"3\"><p><h3>Epic Expanded Knowledge [Epic, Psionic]</h3></p><p>You learn another power.</p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Character level 21st, ability to manifest powers of the normal maximum power level in at least one psionic class.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> You learn one additional power at any level up to the highest level of power you can manifest. You can choose any power, even one that is part of another discipline\'s list or another class\'s list.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> You can gain this feat multiple times. Each time, you learn one new power at any level up to the highest level of power you can manifest.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (55,'Epic Fortitude','Epic','No','No',NULL,NULL,'<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character gains a +4 bonus on all Fortitude saving throws.</p><p/>\n</div>\n',NULL,NULL,'\n      <div topic=\"Epic Fortitude\" level=\"3\"><p><h3>Epic Fortitude [Epic]</h3></p><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character gains a +4 bonus on all Fortitude saving throws.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (56,'Epic Inspiration','Epic','Yes','Yes',NULL,'Cha 25, Perform 30 ranks, bardic music class feature.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> All competence bonuses, dodge bonuses, and morale bonuses granted by the character\'s bardic music ability increase by +1.  If you have the inspire greatness bardic music ability, it grants one additional bonus HD.</p>\n</div>\n',NULL,'A character can gain this feat multiple times. Its effects stack.','\n      <div topic=\"Epic Inspiration\" level=\"3\"><p><h3>Epic Inspiration [Epic]</h3></p><div topic=\"Prerequisites\" level=\"8\"><p><b>Prerequisites:</b> Cha 25, Perform 30 ranks, bardic music class feature.</p>\n</div><div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> All competence bonuses, dodge bonuses, and morale bonuses granted by the character\'s bardic music ability increase by +1.  If you have the inspire greatness bardic music ability, it grants one additional bonus HD.</p>\n</div><div topic=\"Special\" level=\"8\"><p><b>Special:</b> A character can gain this feat multiple times. Its effects stack.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicFeats');
INSERT INTO feat VALUES (57,'Epic Leadership','Epic','No','No',NULL,'Cha 25, Leadership, Leadership score 25.','<div topic=\"Benefit\" level=\"8\"><p><b>Benefit:</b> The character attracts a cohort and followers as shown below on Table: Epic Leadership.  In all other ways Epic Leadership functions as the Leadership feat.</p>\n</div><div topic=\"Table: Epic Leadership\" level=\"8\"><p><b>Table: Epic Leadership</b></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"13\" curcol=\"4\">\n<td><b>Leadership Score</b><br/></td> <td><b>Cohort Level</b><br/></td>\n<td colspan=\"10\" align=\"center\"><b>----------Number of Followers by Level ---------</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"13\" curcol=\"13\">\n<td/>\n<td/>\n<td><b>1st</b><br/></td>\n<td><b>2nd</b><br/></td>\n<td><b>3rd</b><br/></td>\n<td><b>4th</b><br/></td>\n<td><b>5th</b><br/></td>\n<td><b>6th</b><br/></td>\n<td><b>7th</b><br/></td>\n<td><b>8th</b><br/></td>\n<td><b>9th</b><br/></td>\n<td><b>10th</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"13\" curcol=\"13\">\n<td>25<br/></td>\n<td>17th<br/></td>\n<td>135<br/></td>\n<td>13<br/></td>\n<td>7<br/></td>\n<td>4<br/></td>\n<td>2<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"13\" curcol=\"13\">\n<td>26<br/></td>\n<td>18th<br/></td>\n<td>160<br/></td>\n<td>16<br/></td>\n<td>8<br/></td>\n<td>4<br/></td>\n<td>2<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"13\" curcol=\"13\">\n<td>27<br/></td>\n<td>18th<br/></td>\n<td>190<br/></td>\n<td>19<br/></td>\n<td>10<br/></td>\n<td>5<br/></td>\n<td>3<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"13\" curcol=\"13\">\n<td>28<br/></td>\n<td>19th<br/></td>\n<td>220<br/></td>\n<td>22<br/></td>\n<td>11<br/></td>\n<td>6<br/></td>\n<td>3<br/></td>\n<td>2<br/><