td>17<br/></td>\n<td>9<br/></td>\n<td>5<br/></td>\n<td>3<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"13\" curcol=\"13\">\n<td>37<br/></td>\n<td>23rd<br/></td>\n<td>740<br/></td>\n<td>74<br/></td>\n<td>37<br/></td>\n<td>19<br/></td>\n<td>10<br/></td>\n<td>5<br/></td>\n<td>3<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"13\" curcol=\"13\">\n<td>38<br/></td>\n<td>24th<br/></td>\n<td>820<br/></td>\n<td>82<br/></td>\n<td>41<br/></td>\n<td>21<br/></td>\n<td>11<br/></td>\n<td>6<br/></td>\n<td>3<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"13\" curcol=\"13\">\n<td>39<br/></td>\n<td>24th<br/></td>\n<td>910<br/></td>\n<td>91<br/></td>\n<td>46<br/></td>\n<td>23<br/></td>\n<td>12<br/></td>\n<td>6<br/></td>\n<td>3<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"13\" curcol=\"13\">\n<td>40<br/></td>\n<td>25th<br/></td>\n<td>1000<br/></td>\n<td>100<br/></td>\n<td>50<br/></td>\n<td>25<br/></td>\n<td>13<br/></td>\n<td>7<br/></td>\n<td>4<br/></td>\n<td>2<br/></td>\n<td>1<br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"13\" curcol=\"13\">\n<td>per +1<br/></td>\n<td>+1/2*<br/></td>\n<td>+100**<br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n<td><sup><b>!</b></sup><br/></td>\n\n</tr>\n</table><p/>\n</div><div topic=\"Leadership Score\" level=\"8\"><p><b>Leadership Score:</b> A character\'s Leadership score equals his or her level plus any Charisma modifier. Outside factors can affect a character\'s Leadership score, as detailed in the Leadership feat.</p>\n</div><div topic=\"Cohort Level\" level=\"8\"><p><b>Cohort Level:</b> The character can attract a cohort of up to this level. Regardless of the character\'s Leadership score, he or she can\'t recruit a cohort of his or her level or higher.</p>\n</div><div topic=\"Number of Followers by Level\" level=\"8\"><p><b>Number of Followers by Level:</b> The character can lead up to the indicated number of characters of each level.</p><p>*The maximum cohort level increases by 1 for every 2 points of Leadership above 40. **The number of 1st-level followers increases by 100 for every point of Leadership above 40.</p><p><sup><b>!</b></sup>A character can command one-tenth as many 2nd-level followers as 1st-level followers. A character can command one-half as many 3rd-level followers as 2nd-level followers, one-half as many 4th-level followers as 3rd-level followers, and so on (round fractions up, except any fraction less than 1 rounds to 0). A character can\'t have a follower of higher than 20th level.</p><p>Table: Example Special Epic Cohorts presents some creatures that make good cohorts for epic characters.</p><p/>\n</div><div topic=\"Table: Example Special Epic Cohorts\" level=\"8\"><p><b>Table: Example Special Epic Cohorts</b></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Creature</b><br/></td> <td><b>Alignment</b><br/></td>\n<td><b>Level Equivalent</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Angel, astral deva<br/></td>\n<td>Any good<br/></td>\n<td>20nd<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Dragon, ancient silver<br/></td>\n<td>Lawful good<br/></td>\n<td>42nd<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Couatl<br/></td>\n<td>Lawful good<br/></td>\n<td>16th<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Giant, cloud<br/></td>\n<td>Neutral good<br/></td>\n<td>24th<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Ghaele<br/></td>\n<td>Chaotic good<br/></td>\n<td>20st<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Giant, storm<br/></td>\n<td>Ch